// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzzed params: from address, value v, and number of recipients count (to make an array length)
    function testFuzz_property(address from, uint256 v, uint8 count) public {
        // keep count in a small but non-zero range so we have at least one recipient
        uint256 len = uint256(bound(count, 1, 5));

        // deploy a helper that can be toggled to fail or succeed on transferFrom calls
        RecorderFailer helper = new RecorderFailer();

        // Prepare recipients array with distinct addresses generated from fuzzed `from` and index
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) {
            // derive a pseudo-random address from inputs so fuzzer can vary it
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(from, v, i)))));
        }

        // Case that triggers the distinguishing behavior: make the callee fail on its transferFrom
        helper.setShouldFail(true);

        bool ok;
        // call through try/catch to observe whether transfer reverts (reference: reverts if callee failed)
        try c.transfer(from, address(helper), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal rule: the reference contract always reverts (ok == false) when the callee fails.
        // The mutant removes the require and would return true (ok == true) for some inputs here.
        assertTrue(ok == false);
    }
}

// Helper contract that the tested contract will call via low-level call with selector transferFrom(address,address,uint256)
contract RecorderFailer {
    bool public shouldFail;
    // record last call data for observation (not strictly needed but useful)
    address public lastFrom;
    address public lastTo;
    uint256 public lastValue;
    uint256 public calls;

    function setShouldFail(bool s) external {
        shouldFail = s;
    }

    // match the selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        calls += 1;
        lastFrom = from;
        lastTo = to;
        lastValue = value;
        if (shouldFail) {
            // either revert or return false; to exercise both possibilities, revert here
            revert("forced fail");
        }
        return true;
    }
}
